impl NSUserDefaults {
    extern_methods!(
        #[unsafe(method(new))]
        #[unsafe(method_family = new)]
        pub fn new() -> Retained<Self>;
    );
}

impl DefaultRetained for NSUserDefaults {
    #[inline]
    fn default_retained() -> Retained<Self> {
        Self::new()
    }
}

